#!/usr/bin/env python3
"""Generate the hosted passthrough nightly guide from the workflow and suite."""

import argparse
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]
WORKFLOW = ".github/workflows/hosted-passthrough-nightly.yaml"
SUITE = "tests/integration/sdk/openai/test_openai_chat_completions_live.py"
CONFIG = "tests/integration/fixtures/openai/chat-completions-live.yaml"
GUIDE = ROOT / "docs/developing/hosted-passthrough-nightly.md"


def field(pattern, source):
    match = re.search(pattern, source, re.MULTILINE)
    if match is None:
        raise ValueError(f"Missing documentation input: {pattern}")
    return match[1]


def render():
    workflow = (ROOT / WORKFLOW).read_text()
    suite = (ROOT / SUITE).read_text()
    cron = field(r'^\s+- cron: "([^"]+)"$', workflow)
    runner = field(r"^\s+runs-on: (\S+)$", workflow)
    secret = field(r"secrets\.([A-Z_]+)", workflow)
    artifact = field(r"^\s+name: (hosted-\S+-results)$", workflow)
    sdk = field(r'"openai==([^"]+)"', suite)
    pytest = field(r'"pytest==([^"]+)"', suite)
    model = field(r'^MODEL = "([^"]+)"$', suite)

    return f"""# Hosted passthrough nightly

<!-- Generated by .github/scripts/hosted_passthrough_docs.py. Do not edit directly. -->

[Hosted Passthrough Nightly](../../{WORKFLOW}) runs on
`{runner}` at cron `{cron}` (UTC) and supports manual dispatch.
It builds Praxis from the workflow checkout and uses the
`{secret}` Actions secret to call official OpenAI. A missing
secret fails the credential check before the build.

The [SDK suite](../../{SUITE}) sends Chat Completions requests
through the local [Praxis configuration](../../{CONFIG})
over TLS to OpenAI. It uses OpenAI Python `{sdk}` and model
`{model}`. It checks completions and token usage, streaming,
tool result continuation, and the upstream error for an unknown model.

To reproduce locally, build with `cargo build --locked -p praxis-ai-proxy`,
start `target/debug/praxis-ai -c {CONFIG}` from the
repository root, and set `{secret}` in the shell that runs the SDK tests.

```bash
PRAXIS_LIVE_OPENAI_BASE_URL=http://127.0.0.1:8080/v1 \\
  uv run --with pytest=={pytest} --with openai=={sdk} pytest \\
  {SUITE}
```

The run summary records the tested commit and configuration. The
`{artifact}` artifact contains JUnit results. Release CI
qualification records this lane when it finds a run for the exact release
commit. The tests forward the caller's provider key. Gateway authorization,
tenant isolation, credential injection, and retries are outside this suite.
"""


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    expected = render()
    if args.check:
        if not GUIDE.is_file() or GUIDE.read_text() != expected:
            parser.exit(1, f"Regenerate {GUIDE.relative_to(ROOT)} with python3 {Path(__file__).relative_to(ROOT)}\n")
    else:
        GUIDE.write_text(expected)


if __name__ == "__main__":
    main()
